func TestStreamGuard_BoundaryEdgeOfWindow(t *testing.T) {
	// 8.3-BLIND-BOUNDARY-002 | P1 | unit | BOUNDARY-004
	g := badwordGuard(t)
	// Fill the window with clean runes, then split "badword" across the slide.
	filler := strings.Repeat("a", g.Window())
	if _, hit := g.Observe(filler); hit {
		t.Fatal("clean filler fired a hit")
	}
	if _, hit := g.Observe("bad"); hit {
		t.Fatal("partial 'bad' fired a hit")
	}
	m, hit := g.Observe("word")
	if !hit {
		t.Fatal("FALSE-NEGATIVE: term straddling the window-slide boundary not detected")
	}
	if m.Canonical != "badword" {
		t.Fatalf("matched_rule = %q, want badword", m.Canonical)
	}
}

func TestStreamGuard_BoundaryOneRunePerDelta(t *testing.T) {
	// 8.3-BLIND-BOUNDARY-003 | P1 | unit | BOUNDARY-002
	g := badwordGuard(t)
	deltas := strings.Split("badword", "")
	_, idx := observeAll(g, deltas)
	if idx != len(deltas)-1 {
		t.Fatalf("one-rune-per-delta term detected at %d, want the final rune (%d)", idx, len(deltas)-1)
	}
}

func TestStreamGuard_BoundaryLongestTermMaximallySplit(t *testing.T) {
	// 8.3-BLIND-BOUNDARY-004 | P1 | unit | BOUNDARY-003
	longTerm := strings.Repeat("q", 50)
	lex := lexiconWith(t, enRow(longTerm, safetylexicon.CategoryOther, safetylexicon.SeverityLow, 4006))
	g := NewStreamGuard(NewScanner(lex))
	_, idx := observeAll(g, strings.Split(longTerm, ""))
	if idx != len(longTerm)-1 {
		t.Fatalf("maximally-split longest term detected at %d, want %d (window floor must cover it)", idx, len(longTerm)-1)
	}
}

func TestStreamGuard_NotSharedAcrossGoroutines(t *testing.T) {
	// 8.3-BLIND-CONCURRENCY-001 | P0 | unit (-race) | CONCURRENCY-002
	// N goroutines, EACH its OWN guard but a SHARED *Scanner. Must be -race clean;
	// per-request guards isolate the only mutable state.
	scanner := NewScanner(lexiconWith(t, enRow("badword", safetylexicon.CategoryAbuse, safetylexicon.SeverityHigh, 4007)))
	const N = 50
	var wg sync.WaitGroup
	for i := 0; i < N; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			g := NewStreamGuard(scanner)
			if i%2 == 0 {
				if _, hit := observeAll(g, []string{"clean ", fmt.Sprintf("text-%d ", i), "bad", "word"}); hit == -1 {
					t.Errorf("goroutine %d: expected hit on its own stream", i)
				}
			} else {
				if _, hit := observeAll(g, []string{"all ", "clean ", "here ", fmt.Sprintf("%d", i)}); hit != -1 {
					t.Errorf("goroutine %d: unexpected hit on a clean stream", i)
				}
			}
		}(i)
	}
	wg.Wait()
}
